// Normalise the form payload, reject junk, and score the lead.
const SHARED_TOKEN = ''; // set this to match webhookToken in js/config.js, or leave '' to skip

const body = $input.first().json.body ?? $input.first().json;
const data = typeof body === 'string' ? JSON.parse(body) : body;

if (SHARED_TOKEN && data.token !== SHARED_TOKEN) {
  throw new Error('Rejected: bad or missing token');
}

const required = ['name', 'email', 'phone', 'service', 'budget', 'appointmentDate', 'problem'];
const missing = required.filter((k) => !String(data[k] ?? '').trim());
if (missing.length) {
  throw new Error('Rejected: missing fields — ' + missing.join(', '));
}

// Budget → numeric weight, used for routing
const BUDGET_SCORE = {
  'Under £1,000': 1,
  '£1,000 – £5,000': 2,
  '£5,000 – £15,000': 3,
  '£15,000 – £50,000': 4,
  '£50,000+': 5,
  'Not sure yet': 2,
};
const budgetScore = BUDGET_SCORE[data.budget] ?? 1;

// Urgency: how soon they want the appointment
const days = Math.max(
  0,
  Math.round((new Date(data.appointmentDate) - new Date()) / 86400000)
);
const urgencyScore = days <= 3 ? 3 : days <= 14 ? 2 : 1;

// Detail: a considered problem description signals a real buyer
const detailScore = data.problem.length > 200 ? 2 : data.problem.length > 80 ? 1 : 0;

const score = budgetScore * 2 + urgencyScore + detailScore;
const tier = score >= 11 ? 'hot' : score >= 7 ? 'warm' : 'cold';

return [{
  json: {
    ...data,
    firstName: data.name.trim().split(/\s+/)[0],
    email: String(data.email).trim().toLowerCase(),
    phone: String(data.phone).replace(/[^\d+]/g, ''),
    daysUntilAppointment: days,
    score,
    tier,
    receivedAt: new Date().toISOString(),
  },
}];
